namespace sv_0ad0dbeba4f04d278106cbfeac0f6178.Services;

/// <summary>
/// Scoped (per-circuit) service that holds the currently selected warehouse
/// and notifies subscribers when the selection changes.
/// </summary>
public sealed class WarehouseState
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
        ("WH-D", "Warehouse D"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId).Name
        ?? _currentWarehouseId;

    /// <summary>
    /// Raised on the calling thread whenever the warehouse selection changes.
    /// Subscribers must call InvokeAsync / StateHasChanged themselves.
    /// </summary>
    public event Func<Task>? OnChange;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId)
            return;

        _currentWarehouseId = warehouseId;

        if (OnChange is not null)
            await OnChange.Invoke();
    }
}

namespace sv_0ad0dbeba4f04d278106cbfeac0f6178.Services;

/// <summary>
/// Scoped (per-circuit) service that polls for low-stock alerts and
/// notifies all subscribed components when new data arrives.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int LatestLowStockCount { get; private set; }

    /// <summary>
    /// Raised whenever a new alert count is fetched.
    /// All subscribed components receive the notification.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChangedAsync;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call from each component that wants polling to be active.
    /// Polling starts on the first subscriber and stops when the last unsubscribes.
    /// </summary>
    public void Subscribe()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
            StartPolling();
    }

    /// <summary>
    /// Call when a subscribing component is disposed.
    /// </summary>
    public void Unsubscribe()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
            StopPolling();
    }

    private void StartPolling()
    {
        StopPolling();
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start, then every 10 seconds.
        await FetchAndNotifyAsync();

        while (_timer is not null && !ct.IsCancellationRequested)
        {
            try
            {
                if (!await _timer.WaitForNextTickAsync(ct))
                    break;
            }
            catch (OperationCanceledException)
            {
                break;
            }

            await FetchAndNotifyAsync();
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        LatestLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);

        if (OnAlertCountChanged is not null)
            await OnAlertCountChanged.Invoke();
    }

    private async Task HandleWarehouseChangedAsync()
    {
        // When the warehouse changes, immediately re-fetch alerts.
        if (_subscriberCount > 0)
            await FetchAndNotifyAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChangedAsync;
        StopPolling();
    }
}

